'),(1605,115,4,3,'Completed','Nakailang head clean na po kami ng printer (L3110) hindi pa rin po nadedetect yung color blue (cyan)',NULL,'10.40.0.10','2025-12-04 02:16:47','2025-12-04 08:17:12'),(1606,159,1,2,'Completed','Laptop display is flickering and unstable.','Findings:\r\nScreen flickering caused by a faulty laptop display panel. \r\nAction Taken:\r\nRetrieved a dispossessed laptop with a functional screen and used its display panel to replace the defective one. After replacement, the laptop display was tested and confirmed to be working normally.','10.40.0.10','2025-12-04 03:16:50','2025-12-04 03:18:24'),(1607,197,1,2,'Completed','Evaluation of the desktop computer.','Findings: Power on but no display; desktop has no RAM installed. Action Taken:\r\nInspected unit, confirmed no RAM present, checked RAM slots for damage, tested boot with minimal components, verified power supply output, and noted possible onboard display or CPU issue due to lack of POST.\r\nRecommendation: Replacement of the system unit is strongly recommended, as upgrading the existing components would not be cost-effective','10.40.0.10','2025-12-04 07:02:05','2025-12-04 07:11:15'),(1608,187,1,3,'Completed','Error Printing',NULL,'10.40.0.10','2025-12-04 07:43:21','2025-12-04 08:29:03'),(1609,187,1,3,'Completed','Cannot print in Long Bond paper.',NULL,'10.40.0.10','2025-12-09 00:23:23','2025-12-09 03:18:08'),(1610,187,1,3,'Completed','Cannot print in Long Bond paper.',NULL,'10.40.0.10','2025-12-09 00:23:25','2025-12-09 03:17:57'),(1611,147,4,5,'Completed','yung cpu daw po ni maam vee sa lab pwede na daw po painstall :)',NULL,'10.40.0.10','2025-12-09 00:41:28','2025-12-09 05:51:51'),(1612,16,4,6,'Completed','need assistance to set up projector inside the pmma hotel for the opening of bids.',NULL,'10.40.0.10','2025-12-09 00:52:22','2025-12-09 03:18:34'),(1613,15,1,1,'Completed','Kyocera Printer and Laptop wireless connection.',NULL,'10.40.0.10','2025-12-09 00:54:58','2025-12-09 03:12:08'),(1614,