INSERT INTO `tasks` VALUES (1,'Internet/Network Connectivity','Struggling to stay connected? From slow internet speeds and dropped connections to Wi-Fi dead zones, we understand the frustration. Let us tackle your internet and network connectivity issues head-on.','bi bi-wifi'),(2,'PC/Laptop Troubleshooting','Whether it\'s fixing freezing screens, resolving error messages, or diagnosing hardware issues, our experts have the solutions you need to get your device back up and running smoothly.','bi bi-laptop'),(3,'Printer and Other Peripherals Repair','Is your printer refusing to cooperate? Or perhaps your other peripherals like scanners or external drives are acting up? Don\'t worry, we\'re here to help!','bi bi-printer'),(4,'Software Installation and Troubleshooting','Struggling to install software or encountering issues with your current programs? Relax, we\'ve got you covered! Our experts specialize in software installation and troubleshooting.','bi bi-calendar2-check'),(5,'Hardware Installation and Troubleshooting','Dealing with hardware installation woes or facing technical glitches with your devices? Fear not, we\'re here to lend a hand ensuring that your devices are set up correctly and performing optimally.','bi bi-tools'),(6,'Others','Encountering a tech issue that doesn\'t fit into any specific category? Don\'t worry, we\'re still here to help! Our team of experts is well-equipped to tackle a wide range of miscellaneous tech problems.','bi bi-disc');
/*!40000 ALTER TABLE `tasks` ENABLE KEYS */;
UNLOCK TABLES;

